import java.util.*;

// One situation, three models: adjacency matrix, degrees, and a directed (one-way) version
public class GraphModels {
    public static void main(String[] args) {
        String[][] edges = {{"A", "B"}, {"A", "C"}, {"B", "D"}, {"C", "D"}, {"D", "E"}, {"E", "F"}};
        String[] verts = {"A", "B", "C", "D", "E", "F"};
        Map<String, Integer> idx = new HashMap<>();
        for (int i = 0; i < verts.length; i++) idx.put(verts[i], i);
        int n = verts.length;

        int[][] matrix = new int[n][n];
        for (String[] e : edges) {
            matrix[idx.get(e[0])][idx.get(e[1])] = 1;
            matrix[idx.get(e[1])][idx.get(e[0])] = 1; // undirected: the matrix is symmetric
        }
        System.out.println("Adjacency matrix (undirected):");
        System.out.println("    " + String.join(" ", verts));
        int[] degrees = new int[n];
        for (int i = 0; i < n; i++) {
            StringBuilder row = new StringBuilder("  " + verts[i]);
            for (int j = 0; j < n; j++) {
                row.append(" ").append(matrix[i][j]);
                degrees[i] += matrix[i][j];
            }
            System.out.println(row);
        }

        StringBuilder deg = new StringBuilder("Degrees:");
        int total = 0;
        for (int i = 0; i < n; i++) {
            deg.append(" ").append(verts[i]).append("=").append(degrees[i]);
            total += degrees[i];
        }
        System.out.println(deg);
        System.out.println("Handshake lemma: sum of degrees " + total + " = 2 * " + edges.length + " edges");

        // Directed: read each pair (u, v) as a one-way street u -> v
        int[] out = new int[n], in = new int[n];
        for (String[] e : edges) {
            out[idx.get(e[0])]++;
            in[idx.get(e[1])]++;
        }
        StringBuilder dir = new StringBuilder("Directed out/in:");
        int outSum = 0;
        for (int i = 0; i < n; i++) {
            dir.append(" ").append(verts[i]).append("=").append(out[i]).append("/").append(in[i]);
            outSum += out[i];
        }
        System.out.println(dir);
        System.out.println("Sum of out-degrees = sum of in-degrees = " + outSum + " = edges");

        // Every edge adds 2 to the degree total, so an odd total is impossible
        int[][] sequences = {{3, 3, 2, 2, 2}, {3, 3, 3, 2, 2}};
        for (int[] seq : sequences) {
            int sum = Arrays.stream(seq).sum();
            String verdict = sum % 2 == 0 ? "even, not ruled out" : "odd, impossible";
            System.out.println("Degree sequence " + Arrays.toString(seq) + ": sum " + sum + " -> " + verdict);
        }
    }
}

