import java.util.*;

// Every simple path from A to F, the shortest one, and a cycle found by depth-first search
public class PathsAndCycles {
    static final Map<String, List<String>> adj = new TreeMap<>();
    static final Map<String, String> parent = new HashMap<>();

    static void allPaths(String u, String target, List<String> path, List<List<String>> found) {
        if (u.equals(target)) {
            found.add(new ArrayList<>(path));
            return;
        }
        for (String w : adj.get(u)) {
            if (!path.contains(w)) { // a path never repeats a vertex
                path.add(w);
                allPaths(w, target, path, found);
                path.remove(path.size() - 1);
            }
        }
    }

    // In an undirected DFS, reaching an already-visited vertex other than your parent closes a cycle
    static List<String> findCycle(String u, String p) {
        parent.put(u, p);
        for (String w : adj.get(u)) {
            if (w.equals(p)) continue;
            if (parent.containsKey(w)) {
                List<String> cycle = new ArrayList<>(List.of(u));
                String x = u;
                while (!x.equals(w)) {
                    x = parent.get(x);
                    cycle.add(x);
                }
                return cycle;
            }
            List<String> found = findCycle(w, u);
            if (found != null) return found;
        }
        return null;
    }

    public static void main(String[] args) {
        String[][] edges = {{"A", "B"}, {"A", "C"}, {"B", "D"}, {"C", "D"}, {"D", "E"}, {"E", "F"}};
        for (String[] e : edges) {
            adj.computeIfAbsent(e[0], k -> new ArrayList<>()).add(e[1]);
            adj.computeIfAbsent(e[1], k -> new ArrayList<>()).add(e[0]);
        }
        for (List<String> list : adj.values()) Collections.sort(list);

        List<List<String>> paths = new ArrayList<>();
        allPaths("A", "F", new ArrayList<>(List.of("A")), paths);
        System.out.println("Simple paths from A to F: " + paths.size());
        for (List<String> p : paths) System.out.println("  " + String.join(" -> ", p) + "  (length " + (p.size() - 1) + ")");
        List<String> shortest = paths.get(0);
        for (List<String> p : paths) if (p.size() < shortest.size()) shortest = p;
        System.out.println("Shortest: " + String.join(" -> ", shortest) + " with " + (shortest.size() - 1) + " edges");

        List<String> cycle = findCycle("A", null);
        List<String> closed = new ArrayList<>(cycle);
        closed.add(cycle.get(0));
        System.out.println("Cycle found: " + String.join(" -> ", closed) + " (length " + cycle.size() + ")");
        System.out.println("A walk may repeat vertices: A -> B -> A -> C is a walk, not a path");
    }
}

