public class Connectivity {
    static List<List<String>> components(List<String> verts, List<String[]> edges) {
        Map<String, List<String>> adj = new HashMap<>();
        for (String v : verts) adj.put(v, new ArrayList<>());
        for (String[] e : edges) {
            adj.get(e[0]).add(e[1]);
            adj.get(e[1]).add(e[0]);
        }
        Set<String> seen = new HashSet<>();
        List<List<String>> comps = new ArrayList<>();
        for (String s : verts) {
            if (seen.contains(s)) continue;
            List<String> comp = new ArrayList<>();
            Deque<String> queue = new ArrayDeque<>(List.of(s));
            seen.add(s);
            while (!queue.isEmpty()) {
                String u = queue.poll();
                comp.add(u);
                List<String> next = new ArrayList<>(adj.get(u));
                Collections.sort(next);
                for (String w : next) {
                    if (seen.add(w)) queue.add(w);
                }
            }
            Collections.sort(comp);
            comps.add(comp);
        }
        return comps;
    }

    static String show(List<List<String>> comps) {
        List<String> parts = new ArrayList<>();
        for (List<String> c : comps) parts.add("{" + String.join(", ", c) + "}");
        return String.join("  ", parts);
    }

    public static void main(String[] args) {
        List<String> verts = List.of("A", "B", "C", "D", "E", "F", "G", "H");
        List<String[]> edges = new ArrayList<>();
        for (String pair : new String[]{"AB", "AC", "BD", "CD", "DE", "EF", "GH"}) {
            edges.add(new String[]{pair.substring(0, 1), pair.substring(1)});
        }
        List<List<String>> comps = components(verts, edges);
        System.out.println(comps.size() + " components: " + show(comps));
        System.out.println("Connected: " + (comps.size() == 1 ? "yes" : "no"));

        // Remove each edge of the big component in turn and count components again
        List<String> big = comps.get(0);
        List<String[]> bigEdges = new ArrayList<>();
        for (String[] e : edges) if (big.contains(e[0])) bigEdges.add(e);
        List<String> bridges = new ArrayList<>(), safe = new ArrayList<>();
        for (String[] e : bigEdges) {
            List<String[]> rest = new ArrayList<>(bigEdges);
            rest.remove(e);
            (components(big, rest).size() > 1 ? bridges : safe).add(e[0] + "-" + e[1]);
        }
        System.out.println("Bridges: " + String.join(", ", bridges));
        System.out.println("Not bridges (they lie on a cycle): " + String.join(", ", safe));

        List<String[]> more = new ArrayList<>(edges);
        more.add(new String[]{"F", "G"});
        List<List<String>> joined = components(verts, more);
        System.out.println("After adding F-G: " + joined.size() + " component: " + show(joined));
    }
}

