// BFS explores in rings using a queue; DFS goes deep first using a stack
public class BfsDfs {
    public static void main(String[] args) {
        String[][] edges = {{"A", "B"}, {"A", "C"}, {"B", "D"}, {"C", "D"}, {"D", "E"}, {"E", "F"}};
        Map<String, List<String>> adj = new TreeMap<>();
        for (String[] e : edges) {
            adj.computeIfAbsent(e[0], k -> new ArrayList<>()).add(e[1]);
            adj.computeIfAbsent(e[1], k -> new ArrayList<>()).add(e[0]);
        }
        for (List<String> list : adj.values()) Collections.sort(list);

        System.out.println("BFS from A (queue = first in, first out):");
        Map<String, Integer> dist = new HashMap<>(Map.of("A", 0));
        Deque<String> queue = new ArrayDeque<>(List.of("A"));
        while (!queue.isEmpty()) {
            String u = queue.poll();
            for (String w : adj.get(u)) {
                if (!dist.containsKey(w)) {
                    dist.put(w, dist.get(u) + 1);
                    queue.add(w);
                }
            }
            String rest = queue.isEmpty() ? "-" : String.join(" ", queue);
            System.out.println("  visit " + u + " (distance " + dist.get(u) + ")  queue now: " + rest);
        }

        System.out.println("DFS from A (stack = last in, first out):");
        Set<String> seen = new HashSet<>();
        List<String> stack = new ArrayList<>(List.of("A")); // the end of the list is the top
        List<String> order = new ArrayList<>();
        while (!stack.isEmpty()) {
            String u = stack.remove(stack.size() - 1);
            if (seen.contains(u)) continue;
            seen.add(u);
            order.add(u);
            // push in reverse so the alphabetically first neighbor is explored first
            List<String> next = adj.get(u);
            for (int i = next.size() - 1; i >= 0; i--) {
                if (!seen.contains(next.get(i))) stack.add(next.get(i));
            }
            System.out.println("  visit " + u + "  stack now: " + (stack.isEmpty() ? "-" : String.join(" ", stack)));
        }
        System.out.println("DFS order: " + String.join(" ", order));
        System.out.println("BFS gives shortest path lengths: F is " + dist.get("F") + " edges from A");
    }
