def is_connected(vertices, edges):
    vertices = list(vertices)
    if not vertices:
        return True
    nbrs = {v: [] for v in vertices}
    for u, v in edges:
        nbrs[u].append(v)
        nbrs[v].append(u)
    seen, stack = {vertices[0]}, [vertices[0]]
    while stack:
        for w in nbrs[stack.pop()]:
            if w not in seen:
                seen.add(w)
                stack.append(w)
    return len(seen) == len(vertices)

